    @max = max
  end

  def ===(other)
    return false unless other.is_a?(Numeric)
    @min <= other && other < @max
  end

  def match?(number)
    return false unless number.is_a?(Numeric)
    @min <= number && number < @max
  end
end
```

Key points:

- **`===`** is the triple-equals operator, which is what `case`/`when` uses internally for matching. It returns `true` when `min <= number && number < max` (min inclusive, max exclusive), and `false` otherwise (including for non-numeric values).
- **`match?`** provides an explicit way to test whether a number falls within the band.

The `===` method makes it work in `case`/`when` statements, and the numeric comparison logic ensures that `Enumerable#grep` (which uses `===` under the hood) selects exactly the matching numbers in their original order.

