class Band
  def initialize(min, max)
    raise ArgumentError, "min must be less than max" unless min < max
    @min = min
    @max = max
  end

  def match?(value)
    @min <= value && value < @max
  end

  # For use in case statements, Ruby uses ===
  def ===(value)
    match?(value)
  end
end
