class SparseArray
  include Enumerable

  def initialize
    @data = {}
  end

  def []=(index, value)
    @data[index] = value
  end

  def [](index)
    @data[index]
  end

  def each
    return enum_for(:each) unless block_given?

    @data.keys.sort.each do |index|
      yield @data[index]
    end
    self
  end

  def size
    @data.size
  end
  alias_method :length, :size
end
