class Registry
  def initialize
    @objects = []
    @set = {}
  end

  def register(obj)
    # Check if this exact object (by identity) is already registered
    unless @set.key?(obj.object_id)
      @set[obj.object_id] = true
      @objects << obj
    end
    self
  end

  def registered?(obj)
    @set.key?(obj.object_id)
  end

  def size
    @objects.size
  end

  def to_a
    @objects.dup
  end
end
